-- Task 4 bounded case profile. Additive candidate; PDF confirmation remains disabled.
begin;
create table public.research_cases(id uuid primary key,project_id uuid not null references public.projects(id),paper_id uuid not null,revision integer not null default 0,current_version_id uuid,archived_at timestamptz,unique(project_id,id),foreign key(project_id,paper_id) references public.papers(project_id,id));
create table public.research_case_versions(id uuid primary key default gen_random_uuid(),project_id uuid not null,case_id uuid not null,revision integer not null,payload jsonb not null,author_kind text not null check(author_kind in ('human','ai')),review_state text not null check(review_state in ('unreviewed','ai_generated','human_reviewed','human_corrected')),confirmation text not null default 'draft' check(confirmation='draft'),change_reason text not null check(length(btrim(change_reason)) between 1 and 4000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,supersedes_id uuid,source_anchor_id uuid,unique(project_id,id),unique(project_id,case_id,id),unique(project_id,case_id,revision),foreign key(project_id,case_id) references public.research_cases(project_id,id),foreign key(project_id,case_id,supersedes_id) references public.research_case_versions(project_id,case_id,id),foreign key(project_id,source_anchor_id) references public.source_anchors(project_id,id),check(author_kind<>'ai' or review_state='ai_generated'),check((review_state in ('human_reviewed','human_corrected'))=(reviewed_by is not null and reviewed_at is not null)));
alter table public.research_cases add foreign key(project_id,id,current_version_id) references public.research_case_versions(project_id,case_id,id) deferrable initially deferred;
-- Each case is a bounded editing aggregate, with distinct stable scientific entities.
do $$declare family text;begin
 foreach family in array array['compound','reaction','experiment','evidence'] loop
  execute format('create table public.%I(id uuid primary key,project_id uuid not null,case_id uuid not null,current_version_id uuid,unique(project_id,id),unique(project_id,case_id,id),foreign key(project_id,case_id) references public.research_cases(project_id,id))',case when family='evidence' then 'evidence' else family||'s' end);
  execute format('create table public.%I(id uuid primary key default gen_random_uuid(),project_id uuid not null,case_id uuid not null,stable_id uuid not null,case_version_id uuid not null,version_no integer not null,supersedes_id uuid,data jsonb not null,unique(project_id,id),unique(project_id,stable_id,id),unique(project_id,case_version_id,id),unique(project_id,stable_id,version_no),foreign key(project_id,case_id,stable_id) references public.%I(project_id,case_id,id),foreign key(project_id,case_id,case_version_id) references public.research_case_versions(project_id,case_id,id),foreign key(project_id,stable_id,supersedes_id) references public.%I(project_id,stable_id,id))',family||'_versions',case when family='evidence' then 'evidence' else family||'s' end,family||'_versions');
  execute format('alter table public.%I add foreign key(project_id,id,current_version_id) references public.%I(project_id,stable_id,id) deferrable initially deferred',case when family='evidence' then 'evidence' else family||'s' end,family||'_versions');
 end loop;
end$$;
create table public.reaction_participants(project_id uuid not null,case_version_id uuid not null,reaction_version_id uuid not null,compound_version_id uuid not null,position integer not null,role text not null check(role in ('reactant','product','formal_auxiliary')),coefficient numeric check(coefficient>0),primary_for_display boolean not null,primary key(project_id,reaction_version_id,position),foreign key(project_id,case_version_id,reaction_version_id) references public.reaction_versions(project_id,case_version_id,id),foreign key(project_id,case_version_id,compound_version_id) references public.compound_versions(project_id,case_version_id,id));
create table public.claims(id uuid primary key default gen_random_uuid(),project_id uuid not null,case_version_id uuid not null,reaction_version_id uuid not null,data jsonb not null,unique(project_id,id),unique(project_id,case_version_id,id),foreign key(project_id,case_version_id,reaction_version_id) references public.reaction_versions(project_id,case_version_id,id));
create table public.condition_sets(id uuid primary key default gen_random_uuid(),project_id uuid not null,case_version_id uuid not null,experiment_version_id uuid not null,stage text not null check(stage in ('reaction','pretreatment','workup','analysis')),condition_values jsonb not null,unique(project_id,id),unique(project_id,case_version_id,id),foreign key(project_id,case_version_id,experiment_version_id) references public.experiment_versions(project_id,case_version_id,id));
alter table public.evidence_versions add column claim_id uuid not null,add column experiment_version_id uuid not null,add column condition_set_id uuid not null,add column source_anchor_id uuid,add foreign key(project_id,case_version_id,claim_id) references public.claims(project_id,case_version_id,id),add foreign key(project_id,case_version_id,experiment_version_id) references public.experiment_versions(project_id,case_version_id,id),add foreign key(project_id,case_version_id,condition_set_id) references public.condition_sets(project_id,case_version_id,id),add foreign key(project_id,source_anchor_id) references public.source_anchors(project_id,id);
create table public.case_import_batches(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),request_id uuid not null,content_hash text not null,raw_content text not null,proposal jsonb not null,status text not null default 'staged' check(status in ('staged','applied')),result_version_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(project_id,id),unique(project_id,request_id),foreign key(project_id,result_version_id) references public.research_case_versions(project_id,id),check((status='applied')=(result_version_id is not null)),check(content_hash=encode(sha256(convert_to(raw_content,'UTF8')),'hex')),check(proposal=raw_content::jsonb));
-- Validator for the fixed generated JSON Schema subset; no extension installation required.
create function kg_private.case_json_shape(v jsonb,s jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text;x jsonb;t text; n numeric;
begin
 if jsonb_typeof(s->'type')='array' then for x in select value from jsonb_array_elements(s->'type') loop if kg_private.case_json_shape(v,jsonb_set(s,'{type}',x)) then return true;end if;end loop;return false;end if;
 if s ? 'anyOf' then for x in select value from jsonb_array_elements(s->'anyOf') loop if kg_private.case_json_shape(v,x) then return true;end if;end loop;return false;end if;
 if s ? 'enum' and not exists(select from jsonb_array_elements(s->'enum') e where e.value=v) then return false;end if;
 if s ? 'const' and v is distinct from s->'const' then return false;end if;
 t:=s->>'type';if t='integer' then if jsonb_typeof(v)<>'number' then return false;end if;n:=(v#>>'{}')::numeric;if trunc(n)<>n then return false;end if;
 elsif t is not null and jsonb_typeof(v) is distinct from t then return false;end if;
 if t='object' then
  for k in select jsonb_array_elements_text(coalesce(s->'required','[]')) loop if not v ? k then return false;end if;end loop;
  for k,x in select * from jsonb_each(v) loop if not (s->'properties') ? k then return false;end if;if not kg_private.case_json_shape(x,s->'properties'->k) then return false;end if;end loop;
 elsif t='array' then
  if jsonb_array_length(v)<coalesce((s->>'minItems')::integer,0) or jsonb_array_length(v)>coalesce((s->>'maxItems')::integer,100000) then return false;end if;
  for x in select value from jsonb_array_elements(v) loop if not kg_private.case_json_shape(x,s->'items') then return false;end if;end loop;
 elsif t='string' then
  k:=v#>>'{}';if length(btrim(k))<coalesce((s->>'minLength')::integer,0) or length(k)>coalesce((s->>'maxLength')::integer,131072) then return false;end if;
  if s->>'format'='uuid' and k!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false;end if;
  if s ? 'pattern' and k!~(s->>'pattern') then return false;end if;
 elsif t in ('number','integer') then
  n:=(v#>>'{}')::numeric;if s ? 'minimum' and n<(s->>'minimum')::numeric or s ? 'maximum' and n>(s->>'maximum')::numeric or s ? 'exclusiveMinimum' and n<=(s->>'exclusiveMinimum')::numeric or s ? 'exclusiveMaximum' and n>=(s->>'exclusiveMaximum')::numeric then return false;end if;
 end if;return true;
end$$;
create function kg_private.validate_research_case(p_project uuid,p_paper uuid,p jsonb) returns void language plpgsql set search_path='' as $$
declare x jsonb;c jsonb;ids text[];lo numeric;hi numeric;
begin
 if octet_length(p::text)>131072 or not kg_private.case_json_shape(p,$schema${"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"compounds":{"minItems":2,"maxItems":8,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"aliases":{"maxItems":8,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"node_type":{"type":"string","enum":["discrete_molecule","intermediate","polymer","polymer_site","mixture","class"]},"structure_context":{"type":"string","enum":["free","bound","polymer_site","unknown"]},"stereochemistry":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"protonation":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"formula":{"anyOf":[{"type":"string","maxLength":200},{"type":"null"}]},"charge":{"anyOf":[{"type":"integer","minimum":-100,"maximum":100},{"type":"null"}]},"epistemic_status":{"type":"string","enum":["observed","hypothetical","unspecified"]}},"required":["id","name","aliases","node_type","structure_context","stereochemistry","protonation","formula","charge","epistemic_status"],"additionalProperties":false}},"reaction":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"representation_scope":{"type":"string","enum":["net_conversion","elementary_step","pathway_segment"]},"equation_balance_status":{"type":"string","enum":["checked","unchecked","not_applicable","unknown"]},"product_inventory_status":{"type":"string","enum":["complete","partial","unknown"]},"participants":{"minItems":2,"maxItems":16,"type":"array","items":{"type":"object","properties":{"compound_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"role":{"type":"string","enum":["reactant","product","formal_auxiliary"]},"coefficient":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]},"primary_for_display":{"type":"boolean"}},"required":["compound_id","role","coefficient","primary_for_display"],"additionalProperties":false}}},"required":["id","representation_scope","equation_balance_status","product_inventory_status","participants"],"additionalProperties":false},"claim":{"type":"object","properties":{"scope":{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},"proposition":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"asserted_by":{"type":"string","enum":["authors","analyst"]}},"required":["scope","proposition","asserted_by"],"additionalProperties":false},"experiment":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"original_experiment_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"independence_group_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"origin_resolution_status":{"type":"string","enum":["confirmed","unresolved"]},"stage":{"type":"string","enum":["reaction","pretreatment","workup","analysis"]},"conditions":{"maxItems":20,"type":"array","items":{"type":"object","properties":{"key":{"type":"string","minLength":1},"dimension":{"type":"string","minLength":1},"basis":{"type":"string","minLength":1},"unit":{"type":"string"},"value_state":{"type":"string","enum":["reported","not_reported","unknown","not_applicable","ambiguous"]},"kind":{"type":"string","enum":["interval","controlled_term","composition"]},"lower":{"type":["number","null"]},"upper":{"type":["number","null"]},"lower_inclusive":{"type":"boolean"},"upper_inclusive":{"type":"boolean"},"terms":{"type":"array","items":{"type":"string"}},"inventory_complete":{"type":"boolean"},"raw_value_text":{"type":"string"},"raw_unit":{"type":"string"},"derivation":{"type":"string","enum":["reported","calculated"]},"calculation":{"type":["string","null"]}},"required":["key","dimension","basis","unit","value_state","kind","lower","upper","lower_inclusive","upper_inclusive","terms","inventory_complete","raw_value_text","raw_unit","derivation","calculation"],"additionalProperties":false}}},"required":["id","original_experiment_id","independence_group_id","origin_resolution_status","stage","conditions"],"additionalProperties":false},"evidence":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"stance":{"type":"string","enum":["supports","refutes","inconclusive"]},"evidence_type":{"type":"string","enum":["directly_observed","strongly_supported","proposed","adopted_from_prior_literature","speculative"]},"measured_scope":{"anyOf":[{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},{"type":"null"}]},"epistemic_origin":{"type":"string","enum":["experiment_report","authors_interpretation","cited_interpretation","analyst_inference"]},"source_access":{"type":"string","enum":["fulltext","abstract_only","secondary_only","unavailable"]},"strength_rationale":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"alternatives_tested":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"limitations":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"source_anchor_id":{"anyOf":[{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},{"type":"null"}]}},"required":["id","stance","evidence_type","measured_scope","epistemic_origin","source_access","strength_rationale","alternatives_tested","limitations","source_anchor_id"],"additionalProperties":false}},"required":["compounds","reaction","claim","experiment","evidence"],"additionalProperties":false}$schema$::jsonb) then raise exception 'KG_INVALID';end if;
 select array_agg(id) into ids from (select value->>'id' id from jsonb_array_elements(p->'compounds') union all select p#>>'{reaction,id}' union all select p#>>'{experiment,id}' union all select p#>>'{evidence,id}') q;
 if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) then raise exception 'KG_INVALID';end if;
 if not exists(select from jsonb_array_elements(p#>'{reaction,participants}') part where part.value->>'role'='reactant') or not exists(select from jsonb_array_elements(p#>'{reaction,participants}') part where part.value->>'role'='product') then raise exception 'KG_INVALID';end if;
 for x in select value from jsonb_array_elements(p#>'{reaction,participants}') loop if not exists(select from jsonb_array_elements(p->'compounds') comp where comp.value->>'id'=x->>'compound_id') then raise exception 'KG_INVALID';end if;end loop;
 if p#>>'{claim,scope}'='elementary_mechanism' and p#>>'{reaction,representation_scope}'<>'elementary_step' then raise exception 'KG_SCOPE';end if;
 if p#>>'{evidence,evidence_type}'='directly_observed' and p#>>'{evidence,measured_scope}' is distinct from p#>>'{claim,scope}' then raise exception 'KG_SCOPE';end if;
 if p#>>'{evidence,evidence_type}'='strongly_supported' and (jsonb_array_length(p#>'{evidence,alternatives_tested}')=0 or jsonb_array_length(p#>'{evidence,limitations}')=0) then raise exception 'KG_INVALID';end if;
 if p#>>'{experiment,origin_resolution_status}'='confirmed' and (p#>>'{experiment,original_experiment_id}' is null or p#>>'{experiment,independence_group_id}' is null or p#>>'{evidence,evidence_type}'='adopted_from_prior_literature') then raise exception 'KG_ORIGIN';end if;
 for c in select value from jsonb_array_elements(p#>'{experiment,conditions}') loop
  lo:=(c->>'lower')::numeric;hi:=(c->>'upper')::numeric;
  if c->>'value_state'<>'reported' then if lo is not null or hi is not null or jsonb_array_length(c->'terms')<>0 then raise exception 'KG_CONDITIONS';end if;
  elsif c->>'kind'='interval' then
   if jsonb_array_length(c->'terms')<>0 or lo is null and hi is null or lo>hi or lo=hi and (not (c->>'lower_inclusive')::boolean or not (c->>'upper_inclusive')::boolean) then raise exception 'KG_CONDITIONS';end if;
  elsif lo is not null or hi is not null or jsonb_array_length(c->'terms')=0 then raise exception 'KG_CONDITIONS';end if;
  if c->>'value_state'='reported' and c->>'derivation'='calculated' and coalesce(btrim(c->>'calculation'),'')='' then raise exception 'KG_CONDITIONS';end if;
 end loop;
 if p#>>'{evidence,source_anchor_id}' is not null and not exists(select from public.source_anchors a join public.paper_documents d on d.project_id=a.project_id and d.id=a.paper_document_id where a.project_id=p_project and a.id=(p#>>'{evidence,source_anchor_id}')::uuid and d.paper_id=p_paper) then raise exception 'KG_SOURCE';end if;
end$$;
create function kg_private.append_case_entity(p_family text,p_project uuid,p_case uuid,p_version uuid,p_no integer,p_data jsonb) returns uuid language plpgsql set search_path='' as $$
declare stable uuid:=(p_data->>'id')::uuid;old uuid;result uuid;found_case uuid;
begin
 if p_family not in ('compound','reaction','experiment') then raise exception 'KG_INVALID';end if;
 execute format('insert into public.%I(id,project_id,case_id) values($1,$2,$3) on conflict(id) do nothing',p_family||'s') using stable,p_project,p_case;
 execute format('select case_id,current_version_id from public.%I where project_id=$1 and id=$2',p_family||'s') into found_case,old using p_project,stable;
 if found_case is distinct from p_case then raise exception 'KG_CONFLICT';end if;
 execute format('insert into public.%I(project_id,case_id,stable_id,case_version_id,version_no,supersedes_id,data) values($1,$2,$3,$4,$5,$6,$7) returning id',p_family||'_versions') into result using p_project,p_case,stable,p_version,p_no,old,p_data;
 execute format('update public.%I set current_version_id=$1 where project_id=$2 and id=$3',p_family||'s') using result,p_project,stable;
 return result;
end$$;
create function kg_private.persist_research_case(p_project uuid,p_paper uuid,p_case uuid,p_expected integer,p_payload jsonb,p_author text,p_review text,p_reason text) returns uuid language plpgsql set search_path='' as $$
declare old public.research_cases;v uuid;r uuid;experiment uuid;claim uuid;conditions uuid;evidence_v uuid;old_evidence uuid;found_case uuid;x jsonb;mapping jsonb:='{}';n integer:=0;entity uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_project::text,0));perform kg_private.require_owner(p_project,true);
 if not exists(select from public.papers where project_id=p_project and id=p_paper and archived_at is null) then raise exception 'KG_FORBIDDEN';end if;
 perform kg_private.validate_research_case(p_project,p_paper,p_payload);
 select * into old from public.research_cases where project_id=p_project and id=p_case for update;
 if found then if old.paper_id<>p_paper or old.revision is distinct from p_expected then raise exception 'KG_CONFLICT';end if;if old.archived_at is not null then raise exception 'KG_ARCHIVED';end if;
 else if p_expected is distinct from 0 then raise exception 'KG_CONFLICT';end if;insert into public.research_cases(id,project_id,paper_id) values(p_case,p_project,p_paper) returning * into old;end if;
 insert into public.research_case_versions(project_id,case_id,revision,payload,author_kind,review_state,change_reason,created_by,reviewed_by,reviewed_at,supersedes_id,source_anchor_id) values(p_project,p_case,old.revision+1,p_payload,p_author,p_review,p_reason,kg_private.caller_uid(),case when p_review in ('human_reviewed','human_corrected') then kg_private.caller_uid() end,case when p_review in ('human_reviewed','human_corrected') then now() end,old.current_version_id,(p_payload#>>'{evidence,source_anchor_id}')::uuid) returning id into v;
 for x in select value from jsonb_array_elements(p_payload->'compounds') loop entity:=kg_private.append_case_entity('compound',p_project,p_case,v,old.revision+1,x);mapping:=mapping||jsonb_build_object(x->>'id',entity);end loop;
 r:=kg_private.append_case_entity('reaction',p_project,p_case,v,old.revision+1,p_payload->'reaction');
 for x in select value from jsonb_array_elements(p_payload#>'{reaction,participants}') loop
  insert into public.reaction_participants(project_id,case_version_id,reaction_version_id,compound_version_id,position,role,coefficient,primary_for_display) values(p_project,v,r,(mapping->>(x->>'compound_id'))::uuid,n,x->>'role',(x->>'coefficient')::numeric,(x->>'primary_for_display')::boolean);n:=n+1;
 end loop;
 insert into public.claims(project_id,case_version_id,reaction_version_id,data) values(p_project,v,r,p_payload->'claim') returning id into claim;
 experiment:=kg_private.append_case_entity('experiment',p_project,p_case,v,old.revision+1,p_payload->'experiment');
 insert into public.condition_sets(project_id,case_version_id,experiment_version_id,stage,condition_values) values(p_project,v,experiment,p_payload#>>'{experiment,stage}',p_payload#>'{experiment,conditions}') returning id into conditions;
 entity:=(p_payload#>>'{evidence,id}')::uuid;
 insert into public.evidence(id,project_id,case_id) values(entity,p_project,p_case) on conflict(id) do nothing;
 select case_id,current_version_id into found_case,old_evidence from public.evidence where project_id=p_project and id=entity;if found_case is distinct from p_case then raise exception 'KG_CONFLICT';end if;
 insert into public.evidence_versions(project_id,case_id,stable_id,case_version_id,version_no,supersedes_id,data,claim_id,experiment_version_id,condition_set_id,source_anchor_id) values(p_project,p_case,entity,v,old.revision+1,old_evidence,p_payload->'evidence',claim,experiment,conditions,(p_payload#>>'{evidence,source_anchor_id}')::uuid) returning id into evidence_v;
 update public.evidence set current_version_id=evidence_v where project_id=p_project and id=entity;
 update public.research_cases set current_version_id=v,revision=old.revision+1 where project_id=p_project and id=p_case;
 return v;
end$$;
create function public.save_research_case(p_project uuid,p_paper uuid,p_case uuid,p_expected integer,p_payload jsonb,p_reason text) returns uuid language plpgsql set search_path='' as $$begin return kg_private.persist_research_case(p_project,p_paper,p_case,p_expected,p_payload,'human',case when p_expected=0 then 'unreviewed' else 'human_corrected' end,p_reason);end$$;
create function public.review_research_case(p_project uuid,p_case uuid,p_expected integer,p_reason text) returns uuid language plpgsql set search_path='' as $$declare c public.research_cases;v public.research_case_versions;begin
 perform kg_private.require_owner(p_project,true);select * into c from public.research_cases where project_id=p_project and id=p_case;if not found then raise exception 'KG_FORBIDDEN';end if;select * into v from public.research_case_versions where project_id=p_project and id=c.current_version_id;
 return kg_private.persist_research_case(p_project,c.paper_id,p_case,p_expected,v.payload,'human','human_reviewed',p_reason);end$$;
create function public.archive_research_case(p_project uuid,p_case uuid,p_expected integer,p_archived boolean) returns uuid language plpgsql set search_path='' as $$declare result uuid;begin
 perform pg_advisory_xact_lock(hashtextextended(p_project::text,0));perform kg_private.require_owner(p_project,true);if p_archived is null then raise exception 'KG_INVALID';end if;
 update public.research_cases set archived_at=case when p_archived then now() else null end,revision=revision+1 where project_id=p_project and id=p_case and revision=p_expected returning id into result;if result is null then raise exception 'KG_CONFLICT';end if;return result;end$$;
create function public.stage_research_import(p_project uuid,p_request uuid,p_content text) returns uuid language plpgsql set search_path='' as $$declare p jsonb;old public.case_import_batches;result uuid;h text;begin
 perform kg_private.require_owner(p_project,true);if p_content is null or octet_length(p_content)>131072 then raise exception 'KG_INVALID';end if;p:=p_content::jsonb;
 if not kg_private.case_json_shape(p,$schema${"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"schema_version":{"type":"string","const":"research-case/0.1"},"project_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"paper_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"case_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"expected_revision":{"type":"integer","minimum":0,"maximum":9007199254740991},"analysis_run":{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"adapter":{"type":"string","const":"dot_manual_json"},"protocol_version":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"required":["id","adapter","protocol_version"],"additionalProperties":false},"payload":{"type":"object","properties":{"compounds":{"minItems":2,"maxItems":8,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"aliases":{"maxItems":8,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"node_type":{"type":"string","enum":["discrete_molecule","intermediate","polymer","polymer_site","mixture","class"]},"structure_context":{"type":"string","enum":["free","bound","polymer_site","unknown"]},"stereochemistry":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"protonation":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"formula":{"anyOf":[{"type":"string","maxLength":200},{"type":"null"}]},"charge":{"anyOf":[{"type":"integer","minimum":-100,"maximum":100},{"type":"null"}]},"epistemic_status":{"type":"string","enum":["observed","hypothetical","unspecified"]}},"required":["id","name","aliases","node_type","structure_context","stereochemistry","protonation","formula","charge","epistemic_status"],"additionalProperties":false}},"reaction":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"representation_scope":{"type":"string","enum":["net_conversion","elementary_step","pathway_segment"]},"equation_balance_status":{"type":"string","enum":["checked","unchecked","not_applicable","unknown"]},"product_inventory_status":{"type":"string","enum":["complete","partial","unknown"]},"participants":{"minItems":2,"maxItems":16,"type":"array","items":{"type":"object","properties":{"compound_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"role":{"type":"string","enum":["reactant","product","formal_auxiliary"]},"coefficient":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]},"primary_for_display":{"type":"boolean"}},"required":["compound_id","role","coefficient","primary_for_display"],"additionalProperties":false}}},"required":["id","representation_scope","equation_balance_status","product_inventory_status","participants"],"additionalProperties":false},"claim":{"type":"object","properties":{"scope":{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},"proposition":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"asserted_by":{"type":"string","enum":["authors","analyst"]}},"required":["scope","proposition","asserted_by"],"additionalProperties":false},"experiment":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"original_experiment_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"independence_group_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"origin_resolution_status":{"type":"string","enum":["confirmed","unresolved"]},"stage":{"type":"string","enum":["reaction","pretreatment","workup","analysis"]},"conditions":{"maxItems":20,"type":"array","items":{"type":"object","properties":{"key":{"type":"string","minLength":1},"dimension":{"type":"string","minLength":1},"basis":{"type":"string","minLength":1},"unit":{"type":"string"},"value_state":{"type":"string","enum":["reported","not_reported","unknown","not_applicable","ambiguous"]},"kind":{"type":"string","enum":["interval","controlled_term","composition"]},"lower":{"type":["number","null"]},"upper":{"type":["number","null"]},"lower_inclusive":{"type":"boolean"},"upper_inclusive":{"type":"boolean"},"terms":{"type":"array","items":{"type":"string"}},"inventory_complete":{"type":"boolean"},"raw_value_text":{"type":"string"},"raw_unit":{"type":"string"},"derivation":{"type":"string","enum":["reported","calculated"]},"calculation":{"type":["string","null"]}},"required":["key","dimension","basis","unit","value_state","kind","lower","upper","lower_inclusive","upper_inclusive","terms","inventory_complete","raw_value_text","raw_unit","derivation","calculation"],"additionalProperties":false}}},"required":["id","original_experiment_id","independence_group_id","origin_resolution_status","stage","conditions"],"additionalProperties":false},"evidence":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"stance":{"type":"string","enum":["supports","refutes","inconclusive"]},"evidence_type":{"type":"string","enum":["directly_observed","strongly_supported","proposed","adopted_from_prior_literature","speculative"]},"measured_scope":{"anyOf":[{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},{"type":"null"}]},"epistemic_origin":{"type":"string","enum":["experiment_report","authors_interpretation","cited_interpretation","analyst_inference"]},"source_access":{"type":"string","enum":["fulltext","abstract_only","secondary_only","unavailable"]},"strength_rationale":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"alternatives_tested":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"limitations":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"source_anchor_id":{"anyOf":[{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},{"type":"null"}]}},"required":["id","stance","evidence_type","measured_scope","epistemic_origin","source_access","strength_rationale","alternatives_tested","limitations","source_anchor_id"],"additionalProperties":false}},"required":["compounds","reaction","claim","experiment","evidence"],"additionalProperties":false}},"required":["schema_version","project_id","paper_id","case_id","expected_revision","analysis_run","payload"],"additionalProperties":false}$schema$::jsonb) or (p->>'project_id')::uuid<>p_project then raise exception 'KG_INVALID';end if;
 perform kg_private.validate_research_case(p_project,(p->>'paper_id')::uuid,p->'payload');
 if not exists(select from public.papers where project_id=p_project and id=(p->>'paper_id')::uuid and archived_at is null) then raise exception 'KG_FORBIDDEN';end if;
 if exists(select from public.research_cases where project_id=p_project and id=(p->>'case_id')::uuid and paper_id<>(p->>'paper_id')::uuid) then raise exception 'KG_FORBIDDEN';end if;
 h:=encode(sha256(convert_to(p_content,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(p_project::text||p_request::text,0));
 select * into old from public.case_import_batches where project_id=p_project and request_id=p_request;if found then if old.content_hash<>h then raise exception 'KG_CONFLICT';end if;return old.id;end if;
 insert into public.case_import_batches(project_id,request_id,content_hash,raw_content,proposal,created_by) values(p_project,p_request,h,p_content,p,kg_private.caller_uid()) returning id into result;return result;
end$$;
create function public.apply_research_import(p_project uuid,p_batch uuid) returns uuid language plpgsql set search_path='' as $$declare b public.case_import_batches;c public.research_cases;v public.research_case_versions;result uuid;begin
 perform pg_advisory_xact_lock(hashtextextended(p_project::text,0));perform kg_private.require_owner(p_project,true);
 select * into b from public.case_import_batches where project_id=p_project and id=p_batch for update;if not found then raise exception 'KG_FORBIDDEN';end if;if b.status='applied' then return b.result_version_id;end if;
 select * into c from public.research_cases where project_id=p_project and id=(b.proposal->>'case_id')::uuid;
 if found then select * into v from public.research_case_versions where project_id=p_project and id=c.current_version_id;if v.author_kind='human' or v.review_state in ('human_reviewed','human_corrected') then raise exception 'KG_HUMAN_PROTECTED';end if;end if;
 result:=kg_private.persist_research_case(p_project,(b.proposal->>'paper_id')::uuid,(b.proposal->>'case_id')::uuid,(b.proposal->>'expected_revision')::integer,b.proposal->'payload','ai','ai_generated','Applied staged research-case/0.1 import');
 update public.case_import_batches set status='applied',result_version_id=result where project_id=p_project and id=b.id;return result;
end$$;
create role kg_research_writer nologin noinherit nobypassrls;
grant usage on schema public,kg_private to kg_research_writer;
grant execute on function kg_private.caller_uid(),kg_private.require_owner(uuid,boolean),kg_private.has_role(uuid,text[]) to kg_research_writer;
grant select on public.projects,public.papers,public.source_anchors,public.paper_documents to kg_research_writer;
alter policy member_read on public.projects to authenticated,kg_metadata_writer,kg_research_writer;
alter policy member_read on public.papers to authenticated,kg_metadata_writer,kg_research_writer;
alter policy member_read on public.source_anchors to authenticated,kg_research_writer;
alter policy member_read on public.paper_documents to authenticated,kg_research_writer;
do $$declare t text;begin
 foreach t in array array['research_cases','research_case_versions','compounds','compound_versions','reactions','reaction_versions','experiments','experiment_versions','evidence','evidence_versions','reaction_participants','claims','condition_sets','case_import_batches'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,kg_research_writer',t);
  execute format('grant insert on public.%I to kg_research_writer',t);
  execute format('create policy owner_read on public.%I for select to authenticated,kg_research_writer using(kg_private.has_role(project_id,array[''owner'']))',t);
  execute format('create policy owner_insert on public.%I for insert to kg_research_writer with check(kg_private.has_role(project_id,array[''owner'']))',t);
  if t in ('research_cases','compounds','reactions','experiments','evidence','case_import_batches') then
   execute format('grant update(%s) on public.%I to kg_research_writer',case when t='research_cases' then 'revision,current_version_id,archived_at' when t='case_import_batches' then 'status,result_version_id' else 'current_version_id' end,t);
   execute format('create policy owner_update on public.%I for update to kg_research_writer using(kg_private.has_role(project_id,array[''owner''])) with check(kg_private.has_role(project_id,array[''owner'']))',t);
  else execute format('create trigger immutable_record before update or delete on public.%I for each row execute function kg_private.reject_mutation()',t);end if;
 end loop;
end$$;
create trigger audit_change after insert or update on public.research_case_versions for each row execute function kg_private.capture_audit();
create trigger audit_change after insert or update on public.research_cases for each row execute function kg_private.capture_audit();
create trigger audit_change after insert or update on public.case_import_batches for each row execute function kg_private.capture_audit();
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='kg_private' and p.proname in ('case_json_shape','validate_research_case','append_case_entity','persist_research_case') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f);execute format('grant execute on function %s to kg_research_writer',f);end loop;
end$$;
grant kg_research_writer to current_user with inherit false;
grant kg_research_writer to current_user with set true;
grant create on schema public to kg_research_writer;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('save_research_case','review_research_case','archive_research_case','stage_research_import','apply_research_import') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f);execute format('grant execute on function %s to authenticated',f);execute format('alter function %s security definer',f);execute format('alter function %s owner to kg_research_writer',f);
 end loop;
end$$;
revoke create on schema public from kg_research_writer;
grant kg_research_writer to current_user with set false;
do $$begin if has_schema_privilege('kg_research_writer','public','CREATE') or has_schema_privilege('kg_research_writer','auth','USAGE') or pg_has_role(current_user,'kg_research_writer','SET') or pg_has_role(current_user,'kg_research_writer','USAGE') then raise exception 'Unsafe research writer privileges';end if;end$$;
commit;
